#!/bin/zsh
# 바다 쪽 원본 생성. 이름 하나를 인자로 주면 그것만 다시 만든다.
cd /Users/iyeonsang/Desktop/game/games/cat-angler
gfq() { uv run -q --project /Users/iyeonsang/Desktop/game/harness/tools gf --project /Users/iyeonsang/Desktop/game/games/cat-angler "$@" | tail -1 | python3 -c "import sys,json; d=json.loads(sys.stdin.read()); print(d.get('ok'), d.get('files'), d.get('cost_usd'), d.get('error'))"; }
STYLE="pixel art game asset in the exact art style of the reference image, very chunky large pixels, hard pixel edges, no anti-aliasing, thick dark outline, big simple shapes, two or three flat shading tones, minimal detail that survives at small size"
BG="Flat solid pure magenta #FF00FF background everywhere, no shadow, no water, no ground, no text, no labels, no grid lines"
typeset -A A P
A[boat1]=16:9; P[boat1]="$STYLE: a small simple wooden rowboat like the one in the reference, exact side view, bow pointing right, warm brown planks with a lighter top rim, one small bench seat, completely empty (no character, no oars, no rod), whole hull visible including the part below the waterline. Single object centered. $BG."
A[boat2]=4:3; P[boat2]="$STYLE: a small wooden sailing boat in the same style as the rowboat in the reference, exact side view, bow pointing right, warm brown plank hull a bit longer than a rowboat, one short mast with a single cream canvas square sail with two horizontal battens, a tiny teal pennant, a low open deck with a bench, completely empty (no characters), whole hull visible. Single object centered. $BG."
A[boat3]=4:3; P[boat3]="$STYLE: a sturdy wooden fishing vessel in the same style as the rowboat in the reference, exact side view, bow pointing right, long warm brown plank hull with a raised bow, a small cabin with a jade teal tiled roof at the stern (left), one mast with a cream canvas sail with battens, a hanging paper lantern (cream, unlit), a crane arm for nets, open foredeck at the right, completely empty (no characters), whole hull visible. Single object centered. $BG."
A[fishA]=3:2; P[fishA]="$STYLE: a sprite sheet of six different cute fish in a 3 columns by 2 rows grid, each fish alone and centered in its cell with empty space around it, every fish in exact side view facing right with one big round eye and simple fins, like the fish in the reference. Top row: (1) a tiny slender anchovy, pale mint silver with a darker teal back; (2) a small horse mackerel scad, grey green with a pale belly and a forked tail; (3) a flat oval flounder seen from the side lying flat, olive grey green with a few pale spots. Bottom row: (4) a sleek mackerel, blue with wavy dark blue stripes on the back and a white belly; (5) a small plump wrasse, bright teal and turquoise with a mint stripe; (6) a chunky spiny rockfish with a big head and spiky dorsal fin, grey blue with darker blotches. Only cool colours: mint, green, teal, blue, grey. $BG."
A[fishB]=3:2; P[fishB]="$STYLE: a sprite sheet of six different cute sea creatures in a 3 columns by 2 rows grid, each alone and centered in its cell with empty space around it, every one in exact side view facing right with one big round eye, like the fish in the reference. Top row: (1) a round sea bream with a tall body, soft grey violet with lighter belly and a few pale dots; (2) a big strong amberjack, long torpedo body, blue grey back, pale belly, one pale yellowish cream stripe along the side; (3) a moray eel, long thick wavy body stretched horizontally, dark grey green with pale speckles, small open mouth. Bottom row: (4) a hairtail cutlassfish, very long thin ribbon body stretched horizontally, pale silver mint, long low dorsal fin, pointed tail; (5) a deep sea anglerfish, round dark indigo body, huge mouth with small teeth, a glowing light blue lure on a stalk above its head; (6) an oarfish, extremely long ribbon body stretched horizontally, pale blue silver with a tall teal crest on the head and a long fin along the whole back, a few glowing light blue dots. Only cool colours. Friendly and mysterious, not scary. $BG."
A[legend]=16:9; P[legend]="$STYLE: one huge legendary deep sea fish, a mystical ancient carp-like giant with a long graceful body, exact side view facing right, pale mother-of-pearl body shading from cream white to mint and light blue, large calm round eye, long flowing whisker barbels, big flowing fan-like fins and a long veil tail in teal and indigo, a row of glowing light blue dots along its side, big simple scales pattern only on the back. Majestic and gentle, not scary. No red, no gold. Single creature filling most of the image. $BG."
A[props]=3:2; P[props]="$STYLE: a sprite sheet of six small objects in a 3 columns by 2 rows grid, each alone and centered in its cell: (1) a floating wooden crate with rope, (2) a floating corked glass bottle with a rolled paper note inside, lying tilted, pale teal glass, (3) a simple metal fishing hook with a short line loop, dark grey, (4) a white seagull flying, side view facing right, wings raised up, (5) the same seagull, wings level, (6) the same seagull, wings down. $BG."
A[crest]=16:9; P[crest]="$STYLE: one traditional Korean wave ornament like the curling wave crests in the reference image: a single stylised curling wave with a spiral curl at the top, teal and dark teal bands with a thick cream white outline and cream foam tips, symmetrical flat decorative style, wide low shape. Single object centered. $BG."
A[far_shallow]=4:1; P[far_shallow]="$STYLE: a wide horizontal strip of distant scenery for a parallax background: far away low rounded islands and gentle hills as flat pale sage green and pale blue grey silhouettes with one lighter tone, and three small simple cream white pixel clouds floating above them. The islands sit on a perfectly straight horizon line at the very bottom edge of the image. Calm bright morning. No sea, no sky colour. $BG."
A[far_open]=4:1; P[far_open]="$STYLE: a wide horizontal strip of distant scenery for a parallax background: far away steep rocky islands and sea stacks as flat blue grey and slate blue silhouettes with one lighter tone, and several large billowing cream and pale grey pixel clouds above them. The islands sit on a perfectly straight horizon line at the very bottom edge of the image. Open ocean, windy day. No sea, no sky colour. $BG."
A[far_deep]=4:1; P[far_deep]="$STYLE: a wide horizontal strip of distant scenery for a parallax background: far away jagged dark indigo and navy rock spires and cliffs as flat silhouettes with one slightly lighter tone, with long thin pale teal mist cloud bands and a pale crescent moon. The rocks sit on a perfectly straight horizon line at the very bottom edge of the image. Mysterious dusk at the edge of the deep sea. No sea, no sky colour. $BG."
A[mid_shallow]=4:1; P[mid_shallow]="$STYLE: a wide horizontal strip with three separate small coastal rock islets spaced far apart, each a rounded grey green rock with a couple of small twisted pine trees on top (Korean seaside pine style), green and teal tones with dark outline. Their bases sit on a perfectly straight line at the very bottom edge of the image. Large empty gaps between the islets and at both ends. No sea. $BG."
A[mid_open]=4:1; P[mid_open]="$STYLE: a wide horizontal strip with three separate tall bare sea stack rocks spaced far apart, blue grey stone with darker cracks, one with a small stone lighthouse lantern on top, one with seabirds nesting. Their bases sit on a perfectly straight line at the very bottom edge of the image. Large empty gaps between them and at both ends. No sea. $BG."
A[mid_deep]=4:1; P[mid_deep]="$STYLE: a wide horizontal strip with three separate dark jagged rock spires spaced far apart, navy and indigo stone with thin pale teal highlights, one is a broken ancient stone pillar with a carved wave pattern, one has a small glowing pale blue lantern. Their bases sit on a perfectly straight line at the very bottom edge of the image. Large empty gaps between them and at both ends. No sea. $BG."
A[bed_shallow]=8:1; P[bed_shallow]="$STYLE: a wide horizontal strip of shallow sea floor seen in side cross-section: a gently bumpy top surface of pale cream sand with a slightly darker sandy layer below, a few small shells, pebbles, a starfish in pale teal, and short tufts of green seaweed and one small pale coral growing up from the top. The sand fills the image down to the bottom edge and from the far left edge to the far right edge. Above the bumpy sand line is flat solid pure magenta #FF00FF. No text."
A[bed_open]=8:1; P[bed_open]="$STYLE: a wide horizontal strip of ocean floor seen in side cross-section: a bumpy top surface of grey green rock and gravel with darker slate layers below, scattered broken ancient stone blocks and a fallen carved column piece, dark teal kelp tufts growing up from the top. The rock fills the image down to the bottom edge and from the far left edge to the far right edge. Cool colours only. Above the bumpy rock line is flat solid pure magenta #FF00FF. No text."
A[bed_deep]=8:1; P[bed_deep]="$STYLE: a wide horizontal strip of magical deep sea floor seen in side cross-section, like the mother-of-pearl seabed at the bottom of the reference image: a gently wavy top surface of iridescent mother-of-pearl in swirling bands of pale mint, cream white, pale blue and a little pale peach, with a few glowing pale blue pearls and small spiral shells on top. It fills the image down to the bottom edge and from the far left edge to the far right edge. Above the wavy line is flat solid pure magenta #FF00FF. No text."
A[reef]=21:9; P[reef]="$STYLE: an underwater rocky reef mound seen from the side, wide and low with an uneven bumpy top, blue grey and teal rock with darker crevices, covered with a few clumps of teal and mint coral, sea anemones and green seaweed, cool colours only. Flat bottom edge. Single object centered. $BG."
A[wreck]=16:9; P[wreck]="$STYLE: a sunken old wooden sailing ship wreck resting tilted on the sea floor, seen from the side, broken mast, hole in the hull, planks faded to grey teal and dark slate blue (cold underwater colours, not warm brown), kelp and barnacles growing on it. Mysterious, not scary. Flat bottom. Single object centered. $BG."
A[ruins]=3:2; P[ruins]="$STYLE: three separate sunken ancient stone ruin pieces side by side with wide gaps between them, each standing on a flat base, underwater blue grey and slate stone with teal moss: (1) a tall broken round column with a carved wave band, (2) a stone gate of two pillars with a lintel, partly collapsed, (3) a short leaning pillar stump with a fallen block beside it. Like the ruins in the middle depth of the reference image but with outlines. Cool colours only. $BG."
A[pavilion]=4:3; P[pavilion]="$STYLE: an undersea Korean palace pavilion like the jade-roofed pavilion in the reference image: a two-tier traditional Korean pavilion with curved jade green tiled roofs with upturned eaves, teal wooden pillars, a stone base with steps, pale mint lattice railings, a few glowing pale blue lanterns. Jade, teal, mint and indigo colours only, no red, no gold. Exact front side view, flat bottom. Single building centered. $BG."
A[island_far]=21:9; P[island_far]="$STYLE: a small uninhabited island seen from the sea, side view: a sandy cream beach sloping down at the left end where a boat can land, a grassy green hill rising to the right with a few twisted pine trees and one big rock, a few pale flowers on the hilltop. Warm sand and green tones with dark outline. Flat straight bottom edge (it will sit on the water line). Single island filling the width. $BG."
names=(${(k)A}); [[ -n "$1" ]] && names=("$@")
n=0
for k in $names; do
  gfq gen edit "${P[$k]}" --image design/look/target.png --aspect ${A[$k]} --resolution 1K --out assets/raw/sea --name $k &
  n=$((n+1)); (( n % 8 == 0 )) && wait
done
wait
